import { makeReading as make, q, v } from './authoring.mjs';

export const readings = [
make('2級', 'health', 'A Walk Without a Score', [
  `When Emi joined her cousin's walking group, she expected everyone to discuss distance and speed. She had downloaded a phone application that counted every step, and she checked it whenever the group stopped. On the first Saturday, however, her cousin brought a notebook instead of a sports watch. The notebook contained drawings of leaves, old gates, and unusual clouds from previous walks.`,
  `Their route passed a narrow lane behind the shopping street. Emi wanted to hurry because the group was moving more slowly than she had expected. Then her cousin pointed to a small bird carrying grass into a hole in a wall. They stood quietly until it returned. Emi realized that she had walked through the lane many times without noticing that anything lived there.`,
  `At the next meeting, Emi suggested a longer route to a nearby hill. Several members liked the idea, but one person said she would prefer the flat path beside the canal. Rather than asking everyone to follow the hill route, the group chose a meeting place where the two routes ended. Members could select either route and still meet for conversation afterwards. No one had to explain why they preferred one path.`,
  `Emi continued using her application, but she stopped treating its number as the only reason to walk. She sometimes recorded a place she wanted to visit again or something interesting she had heard. For her, the walks became a welcome break from a busy week. She did not claim that the same routine would suit everybody. What mattered was finding an activity she enjoyed enough to continue, while leaving room for other people's different preferences.`,
], [
  q('detail', 'What surprised Emi about her cousin at the first walk?', ['Her cousin recorded things noticed along the route.', 'Her cousin insisted on completing the longest route.', 'Her cousin wanted every member to use the same application.', 'Her cousin refused to stop near the shopping street.'], 0, 'いとこのノートには、過去の散歩で見た葉や門、雲の絵がありました。距離や速度だけを記録していたわけではありません。', 'p1', 'The notebook contained drawings of leaves, old gates, and unusual clouds from previous walks.'),
  q('inference', 'What did watching the bird make Emi realize?', ['The lane had recently been opened to the public.', 'Her application had counted her steps incorrectly.', 'She had been missing details in a familiar place.', 'Her cousin had planned to study birds professionally.'], 2, '何度も通った道なのに生き物に気付いていなかったことから、身近な場所にも見過ごしていたものがあると分かりました。', 'p2', 'Emi realized that she had walked through the lane many times without noticing that anything lived there.'),
  q('detail', 'How did the group handle the different route preferences?', ['It required each member to explain a personal difficulty.', 'It offered two paths that ended at a shared meeting place.', 'It postponed every walk until everyone agreed on one path.', 'It separated the members into permanent groups.'], 1, '二つの道が合流する場所を待ち合わせ先にしたので、道を選びつつ最後は一緒に過ごせました。', 'p3', 'Members could select either route and still meet for conversation afterwards.'),
  q('main-idea', 'What is the main point of Emi’s experience?', ['A phone application always makes walking less enjoyable.', 'Everyone should walk the same distance each weekend.', 'Observing birds is the most important purpose of exercise.', 'An enjoyable routine can allow different goals and preferences.'], 3, 'Emiは自分が続けやすい楽しみを見つけ、他の人の選択も尊重しました。アプリ自体を否定した話ではありません。', 'p4', "What mattered was finding an activity she enjoyed enough to continue, while leaving room for other people's different preferences."),
], [v('route', '経路・道筋'), v('notice', '気付く'), v('preference', '好み・希望')]),

make('2級', 'environment', 'Why the Log Stayed', [
  `After a winter storm, a large branch lay across the grass in Willow Garden. The path was clear, but the broken wood looked untidy. Haru, a new volunteer, offered to carry it away with the other fallen branches. Before he began, an older gardener named Rosa asked him to look carefully at its surface. Small insects were moving beneath the loose bark.`,
  `Rosa explained that the garden contained more than the flowers people came to photograph. Some living things used fallen wood as a place to hide or find food. She was not suggesting that every branch should remain exactly where it fell. Broken wood on a walking path could make the garden difficult to use. This branch, however, was resting in a corner where visitors did not normally walk.`,
  `Haru helped Rosa move it a short distance away from a young plant. They put up a small sign explaining why it had been left there. Over the following months, Haru drew the branch in his notebook. Its shape changed slowly, and different plants grew nearby. Not every visit produced something exciting to record. He learned that looking after a garden sometimes involved watching patiently rather than immediately changing what he saw.`,
  `When a visitor later complained about the corner, Haru listened instead of saying that she knew nothing about nature. She was worried that children might trip over the branch while playing. He showed her the nearby open area and explained the difference between the play space and the quieter corner. The conversation reminded him that a useful explanation should address the concern people actually have. Keeping the branch required both care for living things and attention to how people shared the garden.`,
], [
  q('detail', 'Why did Rosa ask Haru to examine the branch?', ['She wanted him to identify which tree had lost it.', 'It was already being used by small living things.', 'She believed that it was blocking the only walking path.', 'It contained tools another volunteer had forgotten.'], 1, '樹皮の下には虫がいて、倒れた木も生き物の居場所になることを知ってほしかったのです。', 'p1', 'Small insects were moving beneath the loose bark.'),
  q('inference', 'What does Rosa’s explanation suggest about fallen wood?', ['All fallen wood should be removed at the same time.', 'Visitors should be prevented from entering gardens after storms.', 'Its location matters when deciding whether to leave it.', 'Only branches from flowering trees have value.'], 2, '通路上の枝は利用の妨げになり得る一方、この枝は人が普段歩かない隅にありました。場所を踏まえた判断です。', 'p2', 'This branch, however, was resting in a corner where visitors did not normally walk.'),
  q('detail', 'What was the visitor mainly concerned about?', ['Children possibly falling over the branch.', 'The time Haru spent making drawings.', 'A shortage of flowers for photographs.', 'The cost of replacing the garden sign.'], 0, '来園者が心配していたのは、遊ぶ子どもが枝につまずくことでした。', 'p4', 'She was worried that children might trip over the branch while playing.'),
  q('main-idea', 'What did Haru learn from caring for the corner?', ['A garden should be left completely unchanged after a storm.', 'Every visitor needs to become an expert on insects.', 'Making a space look tidy is the only purpose of gardening.', 'Careful observation and an understanding of users both matter.'], 3, '生き物を観察することと、庭を共有する人の具体的な心配に応えることの両方を学びました。', 'p4', 'Keeping the branch required both care for living things and attention to how people shared the garden.'),
], [v('bark', '木の皮・樹皮'), v('surface', '表面'), v('concern', '心配・懸念')]),

make('2級', 'transport', 'The Bus on the Other Side', [
  `Noah was confident that he could reach the museum without a car. The journey planner on his phone showed two buses and a short transfer between them. He allowed extra time and left home early. Yet when his first bus arrived in the town center, he could not find the stop for the second bus. The planner gave the same street name for both stops.`,
  `A driver explained that the next bus left from the opposite side of a busy road. Noah could see the shelter, but a fence prevented him from crossing directly. He had to walk to a crossing farther along the street and then walk back. By the time he reached the shelter, the second bus had gone. The transfer had been short on the map but longer on foot.`,
  `At the museum, Noah told his friend Lea about the experience. Lea used the route regularly and knew the crossing well. She had never thought of mentioning it when giving visitors directions. Together they wrote a short description for the museum's travel page. It included a photograph of the correct shelter and a clear instruction to use the crossing beside the supermarket. They also advised visitors to check the current bus times before leaving.`,
  `The description did not promise that connections would always work. Buses could still be delayed, and some visitors would need more time to walk between stops. Instead, it made a hidden part of the journey visible. Noah was pleased that his difficulty had led to something useful. He still used the planner, but now he paid closer attention to what happened between the lines on the screen. Reaching a destination meant more than knowing the names of the vehicles to board.`,
], [
  q('detail', 'Why did Noah initially have difficulty finding his next bus?', ['The museum had moved to a different town.', 'His phone had shown an old name for the museum.', 'Both stops were identified by the same street name.', 'The first driver had taken him to the wrong town.'], 2, '二つの停留所が同じ通りの名前で示されており、乗り換え先がどちら側か分かりませんでした。', 'p1', 'The planner gave the same street name for both stops.'),
  q('detail', 'Why did the walk to the second stop take longer than expected?', ['Noah stopped to buy food at the supermarket.', 'The second bus changed its route during the journey.', 'The museum required visitors to use another entrance.', 'Noah had to reach a crossing and then walk back.'], 3, '目の前の道を直接渡れず、先にある横断場所まで回る必要があったためです。', 'p2', 'He had to walk to a crossing farther along the street and then walk back.'),
  q('inference', 'Why had Lea not mentioned the crossing before?', ['Its importance was easy for a regular user to overlook.', 'She wanted visitors to avoid using public transport.', 'She believed the supermarket had recently closed.', 'She had never used either bus herself.'], 0, '毎回使っていて当然に知っていることだったため、初めて来る人への説明に必要だと気付いていませんでした。', 'p3', 'Lea used the route regularly and knew the crossing well.'),
  q('main-idea', 'What improvement did the new description provide?', ['It guaranteed that visitors would never miss a bus.', 'It explained a practical step that the basic route information missed.', 'It removed the need to check the bus timetable.', 'It replaced all maps with a photograph of the museum.'], 1, 'バスの名前だけでなく、停留所間を実際にどう移動するかを明確にしました。接続そのものを保証したのではありません。', 'p4', 'Instead, it made a hidden part of the journey visible.'),
], [v('transfer', '乗り換え'), v('shelter', '屋根付きの待合場所'), v('destination', '目的地')]),

make('2級', 'law', 'Permission for the Poster', [
  `The drama club at Westbrook School was preparing a poster for its summer performance. A member found a beautiful photograph of an empty theater on the internet. There was no price beside the image, and it was easy to download. Several students assumed that they could use it simply because anyone could see it online. Their teacher asked them to check before printing the posters.`,
  `The students found the photographer's contact details and sent a message describing the performance. They explained how many posters they hoped to print and where the image would appear. The photographer replied that they could use the picture on twenty printed posters if they included her name. Her message did not mention putting it on the club's social media page.`,
  `One member suggested uploading the poster online as well, since the photographer had already agreed to help. Another student, Ren, pointed out that the reply covered a particular use. Rather than guessing, the club asked a second question. The photographer allowed the online use too, but requested a link to her website. The students saved both messages in the club's shared folder so that the next person preparing the poster could read the conditions.`,
  `For a later event, the club decided to take its own photographs. This gave members more control over the appearance of their materials, although they still discussed who would be photographed and how the images would be used. Ren thought the first poster had taught them a useful habit: describe a planned use clearly and keep a record of the answer. Finding a picture was only the beginning. Understanding the permission attached to it was a separate part of the task.`,
], [
  q('detail', 'What assumption did several students initially make?', ['Every photograph online had been taken by a professional.', 'Printing a poster was more expensive than buying a photograph.', 'A school performance needed no advertising.', 'An image visible online was available for them to use.'], 3, '誰でも見られ、料金も書かれていないことから、そのまま使えると思い込んでいました。', 'p1', 'Several students assumed that they could use it simply because anyone could see it online.'),
  q('detail', 'What did the photographer’s first reply allow?', ['Unlimited printing without her name.', 'Twenty printed posters with her name included.', 'Every future use by any school club.', 'Only a private message to the teacher.'], 1, '最初の返事は、名前を載せた20枚の印刷ポスターへの使用を認める内容でした。', 'p2', 'they could use the picture on twenty printed posters if they included her name'),
  q('inference', 'Why did Ren support asking a second question?', ['He wanted to avoid keeping any written records.', 'He believed the photographer had refused every use.', 'The first permission did not clearly cover online publication.', 'The club had decided to cancel the printed posters.'], 2, '最初の承諾にSNS掲載は含まれていると確認できなかったので、範囲を推測せず問い合わせました。', 'p3', 'Ren, pointed out that the reply covered a particular use'),
  q('main-idea', 'Which habit did the club learn from this experience?', ['Clarify the intended use and preserve the permission given.', 'Assume that one permission covers all later projects.', 'Avoid explaining how many copies will be made.', 'Delete messages once the first poster has been printed.'], 0, '利用方法を具体的に伝え、得られた許可を記録しておくという習慣です。一般的な法的助言ではなく、この架空のやり取りからの学びです。', 'p4', 'describe a planned use clearly and keep a record of the answer'),
], [v('permission', '許可'), v('condition', '条件'), v('record', '記録')]),

make('2級', 'society', 'A Place at the Long Table', [
  `Every autumn, the residents of Maple Court held a meal in their shared courtyard. Each household usually brought a dish, and the tables were pushed together to make one long line. When a new resident named Sam arrived with nothing to share, he stayed near the gate. He had just moved into the building and had not yet unpacked his kitchen equipment.`,
  `A neighbor invited Sam to sit down, but he felt uncomfortable taking food without contributing something. She explained that there were other ways to help. He could carry empty plates, tell people where to find water, or simply join a conversation. Sam began by bringing chairs from the storage room. Soon he was sitting beside an older resident who told him how the courtyard had changed over the years.`,
  `The following spring, Sam helped organize another meal. Remembering his first visit, he suggested changing the invitation. Instead of saying that everyone should bring a dish, it said that people were welcome whether or not they could bring food. A short list described optional jobs for anyone who wanted one. The organizers also left space at the end of the table for people who might decide to come after the meal had begun.`,
  `Not every resident attended. Some preferred to spend the evening quietly, and others had different plans. Sam did not treat their absence as a problem to solve. He wanted the invitation to make joining easier, not to make declining difficult. At the meal, he noticed a student standing near the gate and remembered how that had felt. He offered a seat without first asking what the student had brought. The table was a place to meet neighbors, not a test of what each person could provide.`,
], [
  q('detail', 'Why had Sam brought no dish to the first meal?', ['He had recently moved and his kitchen things were still packed.', 'He had been told that residents were not allowed to cook.', 'He believed the meal was being held at another building.', 'He had already given every neighbor a separate meal.'], 0, '引っ越したばかりで、台所用品をまだ荷ほどきしていなかったためです。', 'p1', 'He had just moved into the building and had not yet unpacked his kitchen equipment.'),
  q('inference', 'What did the neighbor help Sam understand?', ['Only people who cook regularly can organize an event.', 'Sharing food is the only useful contribution.', 'He should leave before the tables become full.', 'Participation can take forms other than bringing a dish.'], 3, '片付けや案内、会話など、食べ物を持参する以外にも加わり方があると伝えました。', 'p2', 'She explained that there were other ways to help.'),
  q('detail', 'How did Sam suggest changing the next invitation?', ['Require all residents to choose a job in advance.', 'Make clear that people could attend without bringing food.', 'Ask late arrivals to wait until the next event.', 'Limit the meal to residents who had attended before.'], 1, '食べ物を持ってこられるかどうかにかかわらず歓迎する、と明記しました。仕事も任意です。', 'p3', 'people were welcome whether or not they could bring food'),
  q('main-idea', 'What kind of gathering did Sam want to create?', ['One that made every resident attend each year.', 'One that rewarded the largest food contribution.', 'One that welcomed participation without turning it into an obligation.', 'One that replaced ordinary conversations with assigned tasks.'], 2, '参加の障壁を減らしつつ、断る自由も尊重する集まりを目指しました。', 'p4', 'He wanted the invitation to make joining easier, not to make declining difficult.'),
], [v('courtyard', '中庭'), v('contribute', '貢献する・持ち寄る'), v('optional', '任意の')]),

make('2級', 'communication', 'Which Friday?', [
  `Lila sent her cousin Ben a short voice message on Sunday. She said, "Let's meet next Friday after lunch at the station." She thought the plan was clear and began looking forward to their visit to an art exhibition. Ben listened while cooking dinner. He replied that he was happy to come, but neither of them wrote the date down.`,
  `On the Friday that followed, Lila waited outside the station with two exhibition tickets. Ben was still at home. When she called, he explained that he had understood "next Friday" to mean the Friday of the following week. They were both surprised. Neither had intended to change the plan, and each had believed that the other understood it in the same way.`,
  `Lila was disappointed, but she avoided starting the conversation by accusing Ben of not listening. Instead, they compared what each had understood. They found that the words "after lunch" were also less precise than they had realized. Lila normally ate at noon, while Ben often finished lunch much later. They agreed to meet the following day and sent each other a written message with the full date, the time, and the station exit.`,
  `The next meeting went smoothly. Ben brought a small sketchbook, and they spent the afternoon drawing objects they liked in the exhibition. Later, Lila did not decide that voice messages were useless. She still used them to share stories or discuss ideas. For arrangements involving tickets and travel, however, she added a written summary and asked Ben to confirm it. She had learned that a message could sound friendly and familiar while still leaving important details open to more than one interpretation.`,
], [
  q('detail', 'What caused the first misunderstanding?', ['Ben was unable to hear any part of the message.', 'They associated the same phrase with different dates.', 'Lila changed the exhibition date without telling Ben.', 'The station had announced an unexpected closure.'], 1, '二人がnext Fridayを別の日付として理解したことが原因です。', 'p2', 'he had understood "next Friday" to mean the Friday of the following week'),
  q('inference', 'Why did Lila and Ben discuss their usual lunch times?', ['They wanted to choose food for the exhibition.', 'They were trying to shorten the visit to the station.', 'They discovered that another part of the plan was unclear.', 'They hoped to avoid ever meeting in the afternoon.'], 2, 'after lunchも生活習慣によって想定時刻が異なり、待ち合わせの指定として曖昧だったと分かったためです。', 'p3', 'the words "after lunch" were also less precise than they had realized'),
  q('detail', 'What did their new written message include?', ['Only the title of the art exhibition.', 'An explanation of why voice messages should be banned.', 'A request that Ben buy another pair of tickets.', 'A complete date, meeting time, and station exit.'], 3, '日付・時間・駅の出口を明記し、確認できる形にしました。', 'p3', 'the full date, the time, and the station exit'),
  q('main-idea', 'What did Lila learn about making arrangements?', ['Familiar language can still need precise confirmation.', 'Written messages are necessary for every kind of conversation.', 'Misunderstandings always show that someone was careless.', 'Friendly messages should avoid discussing practical details.'], 0, '親しい相手への自然な言い方でも複数の解釈があり得るため、予定の重要部分は具体化して確認する、という学びです。', 'p4', 'leaving important details open to more than one interpretation'),
], [v('arrangement', '予定・取り決め'), v('precise', '正確な・明確な'), v('interpretation', '解釈')]),

make('準1級', 'health', 'The Empty Box on the Form', [
  `When a fictional design studio introduced a voluntary wellbeing journal, Marta initially welcomed it. Employees could record activities they found restorative, from gardening to meeting a friend, and reflect on how they wanted to spend their time outside work. Marta liked the questions because they encouraged her to notice small pleasures rather than pursue an impressive target. She wrote about making soup with her father and listening to music on her journey home. The journal seemed to belong to her.`,
  `That impression changed when the studio began inviting employees to share a weekly summary. A notice said that participation remained voluntary, but team leaders asked who had completed the form at the end of each meeting. Colleagues often described long runs or demanding hikes. Marta, whose evenings also involved caring for a relative, started leaving out quieter activities. Nothing in the instructions required this. Nevertheless, she began shaping her account around what seemed likely to receive public approval.`,
  `A colleague named Daniel left the summary blank. When someone joked that he must have had an uneventful week, he explained that he preferred not to discuss his personal time at work. He did not oppose the journal or suggest that others should stop sharing. His objection concerned the assumption that an empty box indicated a failure to do something worthwhile. The box could equally reflect a decision about privacy, a busy week, or a dislike of this particular way of recording experience.`,
  `Their conversation prompted Marta to speak with the person coordinating the journal. Rather than asking for a list of approved activities, she described the difference between choosing to reflect and feeling expected to report. The coordinator removed the public completion question from meetings. Employees who wanted to exchange ideas could join an optional lunchtime conversation, while the journal itself remained private. No manager received a list of people who chose not to attend, and participation was kept separate from discussions of job performance.`,
  `The change did not make every employee enthusiastic. Some still found written reflection unhelpful, and others enjoyed discussing specific exercise goals. The coordinator resisted replacing the old routine with another single model of a successful week. Instead, employees could suggest activities or ignore the journal entirely. Marta returned to writing about cooking, without treating it as evidence that she had achieved a prescribed amount of relaxation. Daniel continued to leave his journal unused and joined colleagues for lunch when he wanted company.`,
  `The episode illustrates a tension in organized efforts to support wellbeing. An invitation can lose some of its freedom when people believe that declining it requires an explanation. That does not make shared activities inherently harmful, nor does it establish that private reflection benefits everyone. It suggests that the conditions surrounding an offer matter as much as its friendly wording. In this studio, protecting the choice not to participate helped preserve the difference between a personal resource and an additional performance expected by the workplace.`,
], [
  q('inference', 'Why did Marta begin omitting quieter activities from her summaries?', ['The journal required activities to last at least an hour.', 'Her father asked her not to mention cooking.', 'She adjusted her account to what seemed socially valued.', 'Her manager had banned descriptions of family life.'], 2, '長いランニングなどが共有される中で、公に評価されそうな内容へ自分の報告を寄せていました。明示的な禁止があったわけではありません。', 'p2', 'she began shaping her account around what seemed likely to receive public approval'),
  q('detail', 'What assumption did Daniel challenge?', ['An uncompleted summary necessarily meant a person had done nothing worthwhile.', 'Employees could enjoy the same activity for different reasons.', 'Some people preferred discussing goals with colleagues.', 'A private journal could be kept outside working hours.'], 0, '空欄を充実していない生活の証拠と見なすことに異議を示しました。プライバシーなど別の理由もあります。', 'p3', 'His objection concerned the assumption that an empty box indicated a failure to do something worthwhile.'),
  q('detail', 'Which change protected employees who did not wish to share?', ['Their team leaders received more detailed private summaries.', 'They were asked to select a different approved activity.', 'Their attendance was discussed during performance reviews.', 'Managers did not receive a list of those declining the optional conversation.'], 3, '不参加者の名簿を管理職へ渡さず、人事評価とも切り離しました。', 'p4', 'No manager received a list of people who chose not to attend'),
  q('main-idea', 'Which conclusion best reflects the passage?', ['Wellbeing activities are effective only when every employee participates.', 'A supportive offer should preserve a meaningful choice to decline.', 'Private journals should replace all workplace conversations.', 'Specific exercise goals are less valuable than quiet activities.'], 1, '支援が追加の業績要求にならないよう、断る自由を実際に守ることが主題です。特定の活動の優劣や万人への効果は述べていません。', 'p6', 'protecting the choice not to participate helped preserve the difference between a personal resource and an additional performance expected by the workplace'),
], [v('restorative', '元気や落ち着きを取り戻す助けになる'), v('prescribed', 'あらかじめ定められた'), v('participate', '参加する')]),

make('準1級', 'environment', 'An Orchard Without a Single Picture', [
  `When the town of Merrow inherited an abandoned orchard, the gift arrived with a photograph taken several decades earlier. Neat rows of fruit trees filled the image, and children stood beside baskets on an open lawn. The photograph quickly became the unofficial plan for restoring the site. Supporters imagined removing the tangled vegetation and recreating the familiar arrangement. To them, the picture offered a clear standard against which progress could be judged, as well as a connection with the town's past.`,
  `Iris, who had been asked to prepare a map of the land, found a more complicated place. Some old trees were still producing fruit, while others had become hollow or fallen. Between them were patches of scrub, shaded ground, and small open spaces. She also noticed that the photograph showed only one corner at one moment. It could not reveal what had grown outside the frame, which paths were muddy in winter, or how much work had been required to maintain the ordered appearance.`,
  `At a meeting, Iris did not argue that the photograph was worthless. It showed the orchard's former purpose and helped residents explain their attachment to it. However, she distinguished a historical record from a complete instruction for the future. Restoring fruit production, providing accessible paths, retaining sheltered areas for wildlife, and preserving every old tree were different aims. They might support one another in some places and conflict in others. Calling all of them restoration did not remove the need to make choices.`,
  `The group therefore discussed particular parts of the site rather than voting on a single image. Near the entrance, it proposed a clear route to a small gathering space. Farther away, some quieter areas would remain difficult to enter. A specialist assessment would guide decisions about damaged trees beside paths, rather than treating age alone as a reason to remove or retain them. Volunteers also considered who would look after newly planted trees after the first season of public enthusiasm had passed.`,
  `One disagreement remained over a line of young trees that had grown where an older row once stood. Removing them would make the historic layout easier to recognize. Keeping some would preserve the site's more recent changes. The eventual plan retained part of the line and used a drawing to show the former arrangement. A few residents found this unsatisfactory because the orchard would never look exactly like the photograph. Others valued the fact that its different periods would remain visible together rather than being reduced to one chosen date.`,
  `The orchard was not presented as a model that every community should copy. Its importance lay in how the group reconsidered its starting assumption. A landscape can carry memories without being frozen into a particular picture. Historical evidence, present conditions, and future responsibilities answer different questions, and none supplies a complete decision by itself. By making those questions explicit, the residents could explain both what they intended to preserve and what they were prepared to change, even when agreement remained incomplete.`,
], [
  q('detail', 'How did the old photograph initially influence the project?', ['It served as an informal picture of what the restored orchard should become.', 'It showed that the town had no connection with the land.', 'It supplied a complete record of maintenance across several seasons.', 'It proved that fruit trees could no longer grow on the site.'], 0, '整った昔の姿が、修復後に再現するべき姿として扱われるようになりました。', 'p1', 'The photograph quickly became the unofficial plan for restoring the site.'),
  q('inference', 'Why did Iris distinguish a historical record from an instruction?', ['She believed residents should forget the orchard’s earlier uses.', 'She wanted all environmental decisions to be made from photographs.', 'The record could inform choices without resolving the competing aims.', 'The photograph had been proven to show a different town.'], 2, '写真には過去を伝える価値がありますが、利用しやすさ・果樹生産・生物の居場所など複数の目標の調整までは決められません。', 'p3', 'They might support one another in some places and conflict in others.'),
  q('detail', 'What did the final decision about the young trees attempt to do?', ['Hide every sign of change since the photograph was taken.', 'Represent the earlier arrangement while retaining part of the later growth.', 'Replace all trees with drawings of the original rows.', 'Postpone every other part of the orchard project indefinitely.'], 1, '一部を残し、昔の配置は図で示すことで、過去の形とその後の変化の両方を伝えようとしました。', 'p5', 'The eventual plan retained part of the line and used a drawing to show the former arrangement.'),
  q('main-idea', 'What is the central argument of the passage?', ['Restoration succeeds only when all residents agree on a single date.', 'Present conditions should always take priority over historical evidence.', 'An inherited landscape should remain completely untouched.', 'Preservation involves explicit choices across past, present, and future needs.'], 3, '過去の資料、現在の条件、将来の管理責任を区別して検討し、残すものと変えるものを説明することが中心です。', 'p6', 'Historical evidence, present conditions, and future responsibilities answer different questions'),
], [v('restoration', '修復・復元'), v('retain', '保持する・残す'), v('explicit', '明確に示された')]),

make('準1級', 'transport', 'The Last Street of the Journey', [
  `By the time a parcel reached Bell Street, it had crossed a sea, passed through a regional depot, and traveled along a motorway. Yet the last few hundred meters could be the most unpredictable part of its journey. The narrow street contained apartments, a bakery, a repair shop, and a school entrance. At different hours, the same section of curb became a delivery space, a place to collect children, or a temporary stopping point for someone helping an older relative out of a car.`,
  `A transport planner named Joel first visited early one morning. The street appeared quiet, and he wondered why residents described it as constantly congested. He returned at midday and again before the school day ended. The visits revealed overlapping demands that were invisible in a map showing only the road's width. The bakery needed flour before its busiest working hours, while the repair shop received irregular deliveries of heavy parts. A uniform rule about when vehicles could stop would affect these activities in different ways.`,
  `One proposal would have moved all deliveries to a depot outside the center, with the final stage completed by small vehicles. Supporters emphasized the possibility of fewer large vans entering the street. A shopkeeper asked what would happen when a delivery missed the depot's departure time. Another pointed out that some goods could be carried easily in small loads, whereas a machine part might require different equipment. These questions did not establish that the proposal was impractical. They identified arrangements that would need to work before its benefits could be assumed.`,
  `Joel also spoke with a driver who knew the street well. The driver explained that a sign saying deliveries could stop for ten minutes did not create an available space. If the space was occupied, the driver had to wait elsewhere or return later. Time saved on the motorway could disappear while searching for somewhere to unload. For residents, meanwhile, a vehicle waiting with its engine running was not an abstract delay in a transport schedule. It was an interruption beside a bedroom window or a blocked view at the crossing.`,
  `The resulting discussion moved beyond the question of which vehicle was smallest. Participants considered different loading periods for different sections of the street, clearer information for occasional drivers, and ways for shops to combine orders when practical. No single arrangement could satisfy every urgent delivery and every resident at all times. The plan therefore included a contact point for reporting recurring conflicts, rather than assuming that publishing a timetable would settle them permanently. The school entrance remained a separate concern requiring attention to people crossing the road.`,
  `Bell Street's experience suggests why the final stage of transport cannot be understood simply as a shorter version of the earlier stages. Movement through a neighborhood involves access to limited shared space and coordination with activities that have their own timing. Efficient travel between distant locations remains valuable, but it does not automatically produce a smooth arrival. A useful account of a journey must include what happens when the vehicle stops, who needs the space then, and which practical burdens have been shifted rather than removed.`,
], [
  q('inference', 'Why were Joel’s visits at different times more informative than his first visit alone?', ['They established that delivery demand was identical throughout the day.', 'They showed changing activities competing for the same space.', 'They proved the road was wider than the map suggested.', 'They allowed him to avoid speaking with residents.'], 1, '時間帯によって荷下ろしや送迎などの需要が重なり、早朝一回の観察では見えない競合が分かったためです。', 'p2', 'The visits revealed overlapping demands that were invisible in a map showing only the road\'s width.'),
  q('purpose', 'What role do the shopkeepers’ questions about the depot serve?', ['They show that large vehicles must be used for every delivery.', 'They demonstrate that no goods can be divided into smaller loads.', 'They prove that the proposed depot has already failed.', 'They identify operational conditions necessary for the proposal to work.'], 3, '出発時刻や荷物ごとの設備など、利点を実現する前提条件を確認しています。案自体が不可能だと証明したわけではありません。', 'p3', 'They identified arrangements that would need to work before its benefits could be assumed.'),
  q('detail', 'What limitation did the delivery driver identify in the stopping rule?', ['Permission to stop did not ensure that the designated space was free.', 'The rule prevented all vehicles from returning later.', 'The time limit applied only to residents’ cars.', 'The sign guaranteed a longer space than the driver needed.'], 0, '停車を許可する表示と、実際に空きがあることは別です。', 'p4', 'a sign saying deliveries could stop for ten minutes did not create an available space'),
  q('main-idea', 'Which statement best summarizes the final paragraph?', ['The distant stages of a journey no longer influence transport efficiency.', 'A small vehicle eliminates conflicts over neighborhood space.', 'Successful arrival requires coordination beyond efficient movement.', 'Publishing a timetable makes further local communication unnecessary.'], 2, '移動中の効率に加え、到着時に誰が場所を必要とするか、負担を別の人へ移していないかまで考える必要があります。', 'p6', 'Efficient travel between distant locations remains valuable, but it does not automatically produce a smooth arrival.'),
], [v('depot', '配送拠点・集積所'), v('congested', '混雑した'), v('coordination', '調整・連携')]),

make('準1級', 'law', 'What the Receipt Could Prove', [
  `The volunteer theater in Brookhaven had used a carved wooden screen in several productions when a former member asked for it back. She said that she had lent it for one summer performance. The current committee believed it had been donated. No one accused anyone else of dishonesty at first; the difficulty was that people remembered the original arrangement differently. The screen was now central to a forthcoming production, which made the uncertainty inconvenient without making either account more accurate.`,
  `The theater's own dispute procedure allowed an uninvolved volunteer to hear both sides and recommend a resolution. This was an internal arrangement, not a court process. The volunteer, Malik, began by separating the question of what had happened from the question of what the committee wished to happen now. Keeping the screen would save money, but that practical advantage did not establish ownership. Equally, the former member's disappointment did not by itself demonstrate that a temporary loan had been agreed.`,
  `A receipt seemed at first to settle the matter. It recorded that the theater had paid a transport company to collect the screen from the member's house. Several committee members regarded this as evidence of a permanent transfer. Malik pointed out that transport costs could have been paid for either a loan or a donation. The receipt supported one narrow claim: the theater had arranged and paid for collection. It did not contain the terms under which the object would remain there.`,
  `An old email added useful but incomplete information. It referred to using the screen "for the summer production," without stating what should happen afterwards. The committee had kept it in storage and used it again, while the former member had not contacted the theater for several years. Malik resisted treating the silence as decisive. It might reflect agreement, but it could also reflect distance, distraction, or an assumption that the screen was still being looked after. He invited both sides to comment on the documents before proposing any solution.`,
  `Eventually, they agreed that the theater would use the screen for its forthcoming performance and then return it on a stated date. The theater would cover the return transport. This compromise did not produce a conclusive account of the original conversation. Instead, it established an arrangement both sides were willing to accept now. Malik's written summary made that distinction clear so that future committee members would not mistake the agreement for proof that one version of the past had been established.`,
  `Afterwards, the theater adopted a simple record for objects arriving on loan or as gifts. It identified the item, the parties, any conditions, and who would keep a copy. The change could not guarantee that disputes would disappear, but it reduced reliance on assumptions surviving unchanged as volunteers came and went. The case illustrated two different tasks: assessing what evidence supports and designing a workable resolution. They can inform each other, yet a convenient outcome should not be presented as stronger evidence than the available records justify.`,
], [
  q('detail', 'What was Malik’s role in the dispute?', ['To act as a judge enforcing a national legal rule.', 'To support the current committee because he managed its budget.', 'To recommend a resolution through the theater’s internal procedure.', 'To decide which actor would use the screen in the next production.'], 2, 'Malikは劇団内の手続きに基づく、当事者ではないボランティアです。裁判官ではありません。', 'p2', 'This was an internal arrangement, not a court process.'),
  q('inference', 'Why did the transport receipt fail to establish ownership?', ['Collection costs were compatible with both a loan and a donation.', 'The receipt identified a different piece of furniture.', 'Neither side agreed that the screen had been collected.', 'The transport company had canceled the collection.'], 0, '運送費を支払うのは貸与でも寄贈でもあり得るため、受領条件までは証明できません。', 'p3', 'transport costs could have been paid for either a loan or a donation'),
  q('detail', 'What did the final agreement establish?', ['A definitive record of the original spoken conversation.', 'An arrangement for current use and a later return.', 'Proof that silence always implies permanent permission.', 'A requirement that the former member buy a new screen.'], 1, '今回の公演で使った後、決まった日に返却するという現在の合意です。過去の会話が確定したわけではありません。', 'p5', 'they agreed that the theater would use the screen for its forthcoming performance and then return it on a stated date'),
  q('main-idea', 'What distinction is central to the passage?', ['Written evidence is always less useful than personal memories.', 'Internal disputes should never be resolved by agreement.', 'Practical costs determine which account of the past is correct.', 'What records prove and what parties can agree to do are separate questions.'], 3, '証拠が何を支えるかと、今どの解決策で合意できるかを混同しない、という区別が中心です。', 'p6', 'assessing what evidence supports and designing a workable resolution'),
], [v('decisive', '決定的な'), v('resolution', '解決・解決策'), v('justify', '正当な根拠を与える')]),

make('準1級', 'society', 'Voices Missing from the Recording', [
  `While preparing an exhibition about a closed clothing factory, a community archivist named Lina found a box of recorded interviews. Former employees described friendships, practical jokes, and pride in making useful goods. Their voices were vivid enough to make the factory seem present again. A designer proposed playing the happiest extracts beside photographs of the final staff picnic. The exhibition could become a warm celebration of a workplace that had once connected many families in the town.`,
  `Lina valued those memories, but she noticed a pattern in the interview list. Most speakers had worked in the same department, and several had been introduced by one former supervisor. Workers from the evening shift were scarcely represented. Temporary employees appeared in photographs but had not been interviewed. The absence did not tell Lina what those people would have said. It did tell her that the surviving recordings could not simply stand for every experience of factory life.`,
  `She contacted several people whose names appeared in old staff notes. One former worker declined to participate because she did not want an argument from years earlier discussed publicly. Another was willing to talk but wanted parts concerning family members excluded. Lina respected those conditions. An archive could become broader without assuming that everyone owed it a complete personal history. She also kept a record of how the new interviews had been obtained, so later researchers could understand why some voices were easier to reach than others.`,
  `The additional conversations complicated rather than replaced the earlier accounts. A worker recalled enjoying the companionship of her colleagues while finding the changing shift schedule difficult. Someone else described learning valuable skills but feeling uncertain whenever a short contract approached its end. These were not necessarily corrections to the cheerful stories. Different experiences could coexist, and even one person could remember the same workplace with affection and frustration. Lina avoided arranging the display as a contest to decide whether the factory had been entirely good or entirely bad.`,
  `Instead, the exhibition placed short extracts around shared themes such as learning, working hours, and leaving. Each extract identified the speaker's role and the interview date, where permission allowed. A separate panel explained how the recordings had been selected and acknowledged gaps in the collection. Visitors could listen to longer sections rather than relying only on a sentence chosen for its emotional force. The final picnic photograph remained, but it no longer served as an uncomplicated summary of everything that had happened inside the factory.`,
  `The completed display was still selective. Space, available recordings, and the wishes of participants all limited what could be included. Lina did not claim to have removed those constraints or recovered every missing account. Her aim was to make the selection visible and prevent a vivid fragment from being mistaken for a complete social history. The exhibition preserved memories while also showing how they had reached the public, leaving visitors room to appreciate personal stories without assuming that the loudest or most accessible voices were the only ones that mattered.`,
], [
  q('inference', 'What could Lina reasonably conclude from the original interview list?', ['Evening workers must have disliked the factory.', 'The first recordings represented only part of the workforce’s experience.', 'Temporary workers had never attended any factory events.', 'The supervisor had instructed every speaker to give a false account.'], 1, '取材された人が特定の部署などに偏っていたため、工場全体の経験を代表するとは言えません。不在の人の意見そのものは分かりません。', 'p2', 'the surviving recordings could not simply stand for every experience of factory life'),
  q('detail', 'How did Lina handle requests to exclude personal details?', ['She ignored them once an interview had started.', 'She treated them as proof that the speaker was unreliable.', 'She canceled the entire exhibition to avoid selection.', 'She respected the conditions set by participants.'], 3, '参加者が話したくない内容や公開したくない部分について、本人の条件を尊重しました。', 'p3', 'Lina respected those conditions.'),
  q('inference', 'What did the new interviews show about the earlier cheerful accounts?', ['They could remain valid alongside more complicated experiences.', 'They had to be removed because all positive memories were misleading.', 'They proved that working schedules had never caused difficulty.', 'They revealed that every worker had held the same opinion.'], 0, '楽しさと不満が同居することもあり、新しい話は必ずしも昔の明るい話の訂正ではありません。', 'p4', 'These were not necessarily corrections to the cheerful stories.'),
  q('main-idea', 'What was Lina’s main purpose in making the selection process visible?', ['To show that a complete history can be recovered from any small collection.', 'To ensure that emotional recordings replace written information.', 'To help visitors understand both the value and limits of the accounts presented.', 'To establish a single final judgment about the factory’s effect on the town.'], 2, '個人の記憶を大切にしながら、選択された断片が社会全体の歴史ではないと分かるようにしました。', 'p6', 'prevent a vivid fragment from being mistaken for a complete social history'),
], [v('archive', '記録資料の集積・資料館'), v('coexist', '共存する'), v('constraint', '制約')]),

make('準1級', 'communication', 'Translating More Than a Word', [
  `At a residents' meeting in the fictional town of Ashford, an interpreter named Nuri helped a newly arrived family discuss a proposed playground. The chair asked whether they could "support the project." Nuri translated the phrase, and the family agreed enthusiastically. A few minutes later, a volunteer passed them a form asking how much time they could contribute to construction. Their surprise revealed that the agreement had not meant the same thing to everyone in the room.`,
  `The family had understood support as approval of the idea. The volunteer had understood it as a willingness to help build the playground. Both meanings were plausible in the discussion, which had moved quickly from planning to practical arrangements. Nuri could have selected a more specific phrase, but she had not known which kind of support the chair intended. The difficulty was therefore not simply a missing equivalent between two languages. An ambiguity in the original question had been carried into the translated conversation.`,
  `Nuri paused the discussion and asked the chair to distinguish the two requests. Did the organizers want an opinion about the playground, an offer of time, or both? Once those questions were separated, the family could answer each one. They approved of the idea but could not promise construction work because of their working hours. They did offer to explain the plan to another family who had missed the meeting. This was a contribution the original form had not made easy to express.`,
  `After the meeting, someone suggested that Nuri should simply make all vague statements clearer while translating. She explained why this was not always possible. Choosing a specific meaning without checking could silently change what a speaker was asking or promising. At other times, a phrase might be deliberately broad because a decision had not yet been made. Her responsibility was not to settle the town's unfinished decisions on behalf of its speakers. When an ambiguity affected an important commitment, she needed room to ask for clarification.`,
  `The chair subsequently introduced a brief pause before asking participants to agree to a task. The exact request was stated, and anyone could explain a condition or ask a question. This helped residents using the same language as the chair as well as those relying on interpretation. The change did not require every casual remark to be defined with legal precision. It focused attention on moments when people were being asked to commit time, money, or responsibility, and where a mistaken assumption would matter later.`,
  `Nuri's experience shows that communication cannot always be repaired by replacing one word with a better word. Shared understanding may depend on distinguishing several intentions that a familiar expression has compressed together. A competent interpreter can make these difficulties visible, but cannot guarantee understanding if participants are unwilling to pause. In Ashford, the most useful change was permission to interrupt an apparently smooth conversation long enough to establish what agreement actually involved. The brief interruption protected a clearer choice instead of being treated as an obstacle to efficient discussion.`,
], [
  q('detail', 'How did the family initially understand “support the project”?', ['As a requirement to pay for all construction materials.', 'As a promise to attend every future meeting.', 'As approval of the playground proposal.', 'As an invitation to become professional interpreters.'], 2, '家族は計画への賛成という意味で受け取り、建設作業の約束とは考えていませんでした。', 'p2', 'The family had understood support as approval of the idea.'),
  q('inference', 'Why could the problem not be attributed only to Nuri’s vocabulary choice?', ['The chair’s original phrase itself left the intended commitment unclear.', 'The family had refused to listen to any translated explanation.', 'The meeting had already approved a detailed construction contract.', 'The volunteer knew that the family opposed the playground.'], 0, '元のsupportにも複数の意味があり、司会が何を求めているか確認できていなかったためです。', 'p2', 'An ambiguity in the original question had been carried into the translated conversation.'),
  q('detail', 'Why did Nuri reject the idea of silently making every vague statement specific?', ['She thought all meetings should avoid practical decisions.', 'She believed participants preferred not to understand one another.', 'She was only willing to translate written forms.', 'Doing so could change a speaker’s intended request or promise.'], 3, '確認なしに意味を限定すると、話し手の依頼や約束を通訳側が変更してしまう可能性があるためです。', 'p4', 'Choosing a specific meaning without checking could silently change what a speaker was asking or promising.'),
  q('main-idea', 'What does the passage suggest about clarification during discussion?', ['It should be avoided whenever a conversation seems fluent.', 'A short pause can protect meaningful agreement about important commitments.', 'It is useful only when participants speak different languages.', 'It requires every informal comment to receive a formal definition.'], 1, '滑らかな会話でも重要な約束の意味を確認する短い中断が必要なことがあります。同じ言語の参加者にも役立ちました。', 'p6', 'The brief interruption protected a clearer choice instead of being treated as an obstacle to efficient discussion.'),
], [v('ambiguity', '曖昧さ・複数の解釈が可能なこと'), v('commitment', '約束・引き受ける責任'), v('clarification', '意味を明確にすること')]),
];
